// Package reports computes the dashboard's reports.
package reports

import (
	"errors"
	"fmt"
	"sort"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// DayRevenue is what an organization took on one day in one currency.
type DayRevenue struct {
	Date     string         `json:"date"` // YYYY-MM-DD
	Currency money.Currency `json:"currency"`
	Amount   int64          `json:"amount"`
	Payments int            `json:"payments"`
}

// Errors.
var (
	ErrInvalidDate  = errors.New("invalid date")
	ErrInvalidRange = errors.New("invalid date range")
)

// MaxDays is the longest range a report covers.
const MaxDays = 366

// Revenue adds up the organization's succeeded payments per day and currency, from the day from to the day to (YYYY-MM-DD,
// both included). Days are UTC days. The result is in date order, currencies in alphabetical order within a day; days
// without payments are left out.
func Revenue(st *store.Store, orgID, from, to string) ([]DayRevenue, error) {
	start, err := time.Parse(time.DateOnly, from)
	if err != nil {
		return nil, fmt.Errorf("%w: from %q", ErrInvalidDate, from)
	}
	last, err := time.Parse(time.DateOnly, to)
	if err != nil {
		return nil, fmt.Errorf("%w: to %q", ErrInvalidDate, to)
	}
	if last.Before(start) {
		return nil, fmt.Errorf("%w: to is before from", ErrInvalidRange)
	}
	if last.Sub(start) >= MaxDays*24*time.Hour {
		return nil, fmt.Errorf("%w: at most %d days", ErrInvalidRange, MaxDays)
	}
	end := last.AddDate(0, 0, 1)
	type key struct {
		day string
		cur money.Currency
	}
	sums := map[key]*DayRevenue{}
	for _, p := range st.Payments(orgID, "") {
		if p.Status != store.PaymentSucceeded || p.CreatedAt.Before(start) || !p.CreatedAt.Before(end) {
			continue
		}
		k := key{p.CreatedAt.UTC().Format(time.DateOnly), p.Currency}
		d, ok := sums[k]
		if !ok {
			d = &DayRevenue{Date: k.day, Currency: k.cur}
			sums[k] = d
		}
		d.Amount += p.Amount
		d.Payments++
	}
	out := make([]DayRevenue, 0, len(sums))
	for _, d := range sums {
		out = append(out, *d)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Date != out[j].Date {
			return out[i].Date < out[j].Date
		}
		return out[i].Currency < out[j].Currency
	})
	return out, nil
}
package reports

import (
	"errors"
	"testing"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

func TestRevenue(t *testing.T) {
	st := store.New()
	day := func(d, h int) time.Time { return time.Date(2026, 3, d, h, 0, 0, 0, time.UTC) }
	o, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, day(1, 0))
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", day(1, 0))
	inv, _ := st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, day(1, 0))
	pay := func(amount int64, cur money.Currency, status store.PaymentStatus, at time.Time) {
		if _, err := st.CreatePayment(store.Payment{OrgID: o.ID, InvoiceID: inv.ID, Amount: amount, Currency: cur, Status: status}, at); err != nil {
			t.Fatal(err)
		}
	}
	pay(1000, money.USD, store.PaymentSucceeded, day(2, 9))
	pay(500, money.USD, store.PaymentSucceeded, day(2, 15))
	pay(700, money.EUR, store.PaymentSucceeded, day(2, 12))
	pay(999, money.USD, store.PaymentFailed, day(2, 13))
	pay(300, money.USD, store.PaymentSucceeded, day(4, 12))
	pay(100, money.USD, store.PaymentSucceeded, day(6, 12)) // after the range
	got, err := Revenue(st, o.ID, "2026-03-01", "2026-03-05")
	if err != nil {
		t.Fatal(err)
	}
	want := []DayRevenue{
		{Date: "2026-03-02", Currency: money.EUR, Amount: 700, Payments: 1},
		{Date: "2026-03-02", Currency: money.USD, Amount: 1500, Payments: 2},
		{Date: "2026-03-04", Currency: money.USD, Amount: 300, Payments: 1},
	}
	if len(got) != len(want) {
		t.Fatalf("Revenue = %+v", got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("day %d = %+v, want %+v", i, got[i], want[i])
		}
	}
}

func TestRevenueRange(t *testing.T) {
	st := store.New()
	for _, c := range []struct {
		from, to string
		want     error
	}{
		{"2026-03-01", "2026/03/05", ErrInvalidDate},
		{"yesterday", "2026-03-05", ErrInvalidDate},
		{"2026-03-05", "2026-03-01", ErrInvalidRange},
		{"2026-01-01", "2027-01-02", ErrInvalidRange},
	} {
		if _, err := Revenue(st, "org_x", c.from, c.to); !errors.Is(err, c.want) {
			t.Errorf("Revenue(%s, %s) = %v, want %v", c.from, c.to, err, c.want)
		}
	}
	if got, err := Revenue(st, "org_x", "2026-01-01", "2026-12-31"); err != nil || len(got) != 0 {
		t.Fatalf("a full year: %v, %v", got, err)
	}
}
package api

import (
	"errors"
	"net/http"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/reports"
)

// revenueReport answers the money taken per day: ?from=YYYY-MM-DD&to=YYYY-MM-DD (both included).
func (s *Server) revenueReport(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	q := r.URL.Query()
	days, err := reports.Revenue(s.store, p.OrgID, q.Get("from"), q.Get("to"))
	switch {
	case errors.Is(err, reports.ErrInvalidDate):
		writeError(w, http.StatusBadRequest, "invalid_date", err.Error())
		return
	case errors.Is(err, reports.ErrInvalidRange):
		writeError(w, http.StatusBadRequest, "invalid_range", err.Error())
		return
	case err != nil:
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"days": days})
}

