// Package reports computes the dashboard's reports.
package reports

import (
	"errors"
	"fmt"
	"sort"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// DayRevenue is what an organization took on one day in one currency.
type DayRevenue struct {
	Date     string         `json:"date"` // YYYY-MM-DD
	Currency money.Currency `json:"currency"`
	Amount   int64          `json:"amount"`
	Payments int            `json:"payments"`
}

// Group is how a revenue report divides its range into buckets.
type Group string

// Groups. A week starts on Monday; a month is a calendar month.
const (
	GroupDay   Group = "day"
	GroupWeek  Group = "week"
	GroupMonth Group = "month"
)

// Valid reports whether g is a known group.
func (g Group) Valid() bool { return g == GroupDay || g == GroupWeek || g == GroupMonth }

// Errors.
var (
	ErrInvalidDate  = errors.New("invalid date")
	ErrInvalidRange = errors.New("invalid date range")
	ErrInvalidGroup = errors.New("invalid group")
)

// MaxDays is the longest range a report covers.
const MaxDays = 366

// Bucket is what an organization took in one day, week or month, in each currency. Start is the first day of the
// bucket (YYYY-MM-DD) in the organization's time zone.
type Bucket struct {
	Start    string                   `json:"start"`
	Amounts  map[money.Currency]int64 `json:"amounts"`
	Payments int                      `json:"payments"`
}

// GroupedRevenue is a revenue report: the buckets from the one holding from to the one holding to, in order.
type GroupedRevenue struct {
	TimeZone string   `json:"time_zone"`
	Group    Group    `json:"group"`
	Buckets  []Bucket `json:"buckets"`
}

// Revenue adds up the organization's succeeded payments per day and currency, from the day from to the day to (YYYY-MM-DD,
// both included). Days are days in the organization's time zone. The result is in date order, currencies in alphabetical
// order within a day; days without payments are left out.
func Revenue(st *store.Store, orgID, from, to string) ([]DayRevenue, error) {
	rep, err := RevenueByGroup(st, orgID, from, to, GroupDay)
	if err != nil {
		return nil, err
	}
	out := []DayRevenue{}
	for _, b := range rep.Buckets {
		curs := make([]money.Currency, 0, len(b.Amounts))
		for c := range b.Amounts {
			curs = append(curs, c)
		}
		sort.Slice(curs, func(i, j int) bool { return curs[i] < curs[j] })
		for _, c := range curs {
			out = append(out, DayRevenue{Date: b.Start, Currency: c, Amount: b.Amounts[c], Payments: b.Payments})
		}
	}
	return out, nil
}

// RevenueByGroup adds up the organization's succeeded payments per bucket and currency, from the day from to the day to
// (YYYY-MM-DD, both included). Days are days in the organization's time zone, so a payment belongs to the day, in that
// time zone, when it was made. An empty group means day. Every bucket from the one holding from to the one holding to is
// in the result, in order, also those without payments.
func RevenueByGroup(st *store.Store, orgID, from, to string, group Group) (GroupedRevenue, error) {
	start, err := time.Parse(time.DateOnly, from)
	if err != nil {
		return GroupedRevenue{}, fmt.Errorf("%w: from %q", ErrInvalidDate, from)
	}
	last, err := time.Parse(time.DateOnly, to)
	if err != nil {
		return GroupedRevenue{}, fmt.Errorf("%w: to %q", ErrInvalidDate, to)
	}
	if last.Before(start) {
		return GroupedRevenue{}, fmt.Errorf("%w: to is before from", ErrInvalidRange)
	}
	if last.Sub(start) >= MaxDays*24*time.Hour {
		return GroupedRevenue{}, fmt.Errorf("%w: at most %d days", ErrInvalidRange, MaxDays)
	}
	if group == "" {
		group = GroupDay
	}
	if !group.Valid() {
		return GroupedRevenue{}, fmt.Errorf("%w: %q", ErrInvalidGroup, group)
	}
	org, ok := st.Org(orgID)
	if !ok {
		return GroupedRevenue{}, store.ErrNotFound
	}
	loc, err := time.LoadLocation(org.TimeZone)
	if err != nil {
		return GroupedRevenue{}, fmt.Errorf("organization time zone %q: %w", org.TimeZone, err)
	}

	// Buckets are counted in civil dates, held as UTC midnights so that adding days and months never meets daylight saving.
	buckets := []Bucket{}
	index := map[time.Time]int{}
	for b := bucketOf(start, group); !b.After(bucketOf(last, group)); b = nextBucket(b, group) {
		index[b] = len(buckets)
		buckets = append(buckets, Bucket{Start: b.Format(time.DateOnly), Amounts: map[money.Currency]int64{}})
	}
	for _, p := range st.Payments(orgID, "") {
		if p.Status != store.PaymentSucceeded {
			continue
		}
		local := p.CreatedAt.In(loc)
		day := time.Date(local.Year(), local.Month(), local.Day(), 0, 0, 0, 0, time.UTC)
		if day.Before(start) || day.After(last) {
			continue
		}
		b := &buckets[index[bucketOf(day, group)]]
		b.Amounts[p.Currency] += p.Amount
		b.Payments++
	}
	return GroupedRevenue{TimeZone: org.TimeZone, Group: group, Buckets: buckets}, nil
}

// bucketOf returns the first day of the bucket that holds day (a UTC midnight).
func bucketOf(day time.Time, g Group) time.Time {
	switch g {
	case GroupWeek:
		return day.AddDate(0, 0, -((int(day.Weekday()) + 6) % 7)) // Monday is the first day of the week
	case GroupMonth:
		return time.Date(day.Year(), day.Month(), 1, 0, 0, 0, 0, time.UTC)
	}
	return day
}

// nextBucket returns the first day of the bucket after b.
func nextBucket(b time.Time, g Group) time.Time {
	switch g {
	case GroupWeek:
		return b.AddDate(0, 0, 7)
	case GroupMonth:
		return b.AddDate(0, 1, 0)
	}
	return b.AddDate(0, 0, 1)
}

